settings.custom_liquid:
{% comment %}
  Gratis Verzending Balk — free-shipping-bar.liquid
  Gebruik: {% render 'free-shipping-bar' %}
  Pas de drempel aan via 'free_shipping_threshold' hieronder.
{% endcomment %}

{% assign free_shipping_threshold = 6995 %}
{% assign cart_total = cart.total_price %}
{% assign remaining_cents = free_shipping_threshold | minus: cart_total %}
{% assign progress_pct = cart_total | times: 100 | divided_by: free_shipping_threshold %}
{% if progress_pct > 100 %}{% assign progress_pct = 100 %}{% endif %}

{% if cart_total > 0 %}
<div class="free-shipping-bar" id="free-shipping-bar">
  <div class="fsb-inner">

    {% if cart_total >= free_shipping_threshold %}
      <p class="fsb-message fsb-message--done" id="fsb-message">
        <svg class="fsb-svg-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="#74C200" aria-hidden="true">
          <path fill-rule="evenodd" d="M2.93 2.93a9.997 9.997 0 0 1 14.141 0 10 10 0 0 1 2.93 7.07 10.004 10.004 0 0 1-10 10A10.004 10.004 0 0 1 0 10a10 10 0 0 1 2.928-7.07Zm12.227 4.673A1.087 1.087 0 0 0 15.07 6.1a1.01 1.01 0 0 0-1.456.09l-4.516 5.415-2.752-2.801a1.01 1.01 0 0 0-1.46 0 1.087 1.087 0 0 0 0 1.504l3.44 3.546c.2.207.476.32.76.311a1.02 1.02 0 0 0 .742-.358l5.33-6.205Z"/>
        </svg>
        Gefeliciteerd! Je ontvangt <strong>gratis verzending</strong>.
      </p>
    {% else %}
      <p class="fsb-message" id="fsb-message">
        Voeg nog <strong id="fsb-remaining" class="fsb-amount">{{ remaining_cents | money }}</strong> toe voor <strong>gratis verzending</strong>
      </p>
    {% endif %}

    <div class="fsb-track" role="progressbar" aria-valuenow="{{ progress_pct }}" aria-valuemin="0" aria-valuemax="100" aria-label="Voortgang gratis verzending" id="fsb-track">
      <div
        class="fsb-fill{% if cart_total >= free_shipping_threshold %} fsb-fill--done{% endif %}"
        style="width: {{ progress_pct }}%;"
        id="fsb-fill"
      ></div>
    </div>

    <div class="fsb-labels">
      <span id="fsb-current" class="fsb-amount">{{ cart_total | money }}</span>
      <span class="fsb-amount">{{ free_shipping_threshold | money }}</span>
    </div>

  </div>
</div>
{% endif %}

<style>
  .free-shipping-bar {
    padding: 12px 16px;
    background: #ffffff;
    border: 1px solid rgba(160, 178, 201, 0.8);
    border-radius: 8px;
    font-family: var(--font-body--family, Helvetica, Arial, sans-serif);
    margin-bottom: 24px;
  }

  .fsb-inner {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .fsb-message {
    margin: 0;
    font-size: var(--font-size--sm, 0.875rem);
    font-family: var(--font-body--family, Helvetica, Arial, sans-serif);
    font-style: var(--font-body--style, normal);
    color: var(--color-foreground-muted, #5f5e5a);
    line-height: var(--line-height--body-normal, 1.4);
  }

  .fsb-message strong {
    color: var(--color-foreground, #1a1a18);
    font-weight: var(--font-body--weight, 700);
  }

  .fsb-message--done {
    display: flex;
    align-items: center;
    gap: 6px;
    color: #4a7200;
    font-weight: var(--font-body--weight, 700);
  }

  .fsb-message--done strong {
    color: #4a7200;
  }

  .fsb-amount {
    font-family: var(--cart-secondary-font-family, var(--font-subheading--family, Helvetica, Arial, sans-serif));
    font-style: var(--cart-secondary-font-style, var(--font-subheading--style, normal));
    font-weight: var(--cart-secondary-font-weight, var(--font-subheading--weight, 700));
    font-size: var(--font-size--sm, 0.875rem);
    line-height: 1;
    color: var(--color-foreground, #001d3d);
  }

  .fsb-svg-icon {
    width: 18px;
    height: 18px;
    flex-shrink: 0;
  }

  .fsb-track {
    height: 6px;
    background: rgb(var(--color-foreground-rgb, 0 29 61) / 0.08);
    border-radius: 999px;
    overflow: hidden;
  }

  .fsb-fill {
    height: 100%;
    border-radius: 999px;
    background: #74C200;
    transition: width 0.5s var(--ease-out-quad, cubic-bezier(0.32, 0.72, 0, 1));
    min-width: 4px;
  }

  .fsb-fill--done {
    background: #74C200;
  }

  .fsb-labels {
    display: flex;
    justify-content: space-between;
  }
</style>

<script>
(function () {
  const THRESHOLD_CENTS = {{ free_shipping_threshold }};

  function formatMoney(cents) {
    return '€' + (cents / 100).toFixed(2).replace('.', ',');
  }

  const SVG_CHECK = '<svg class="fsb-svg-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="#74C200" aria-hidden="true"><path fill-rule="evenodd" d="M2.93 2.93a9.997 9.997 0 0 1 14.141 0 10 10 0 0 1 2.93 7.07 10.004 10.004 0 0 1-10 10A10.004 10.004 0 0 1 0 10a10 10 0 0 1 2.928-7.07Zm12.227 4.673A1.087 1.087 0 0 0 15.07 6.1a1.01 1.01 0 0 0-1.456.09l-4.516 5.415-2.752-2.801a1.01 1.01 0 0 0-1.46 0 1.087 1.087 0 0 0 0 1.504l3.44 3.546c.2.207.476.32.76.311a1.02 1.02 0 0 0 .742-.358l5.33-6.205Z"/></svg>';

  function updateBar(totalCents) {
    const bar     = document.getElementById('free-shipping-bar');
    const fill    = document.getElementById('fsb-fill');
    const track   = document.getElementById('fsb-track');
    const message = document.getElementById('fsb-message');
    const current = document.getElementById('fsb-current');

    // Winkelwagen leeg → balk volledig verbergen
    if (totalCents <= 0) {
      if (bar) bar.style.display = 'none';
      return;
    }

    // Winkelwagen heeft inhoud → balk tonen
    if (bar) bar.style.display = '';

    if (!fill || !message) return;

    const pct = Math.min((totalCents / THRESHOLD_CENTS) * 100, 100);
    fill.style.width = pct.toFixed(2) + '%';
    track.setAttribute('aria-valuenow', Math.round(pct));

    if (current) current.textContent = formatMoney(totalCents);

    if (totalCents >= THRESHOLD_CENTS) {
      fill.classList.add('fsb-fill--done');
      message.className = 'fsb-message fsb-message--done';
      message.innerHTML = SVG_CHECK + 'Gefeliciteerd! Je ontvangt <strong>gratis verzending</strong>.';
    } else {
      fill.classList.remove('fsb-fill--done');
      message.className = 'fsb-message';
      message.innerHTML = 'Voeg nog <strong id="fsb-remaining" class="fsb-amount">' + formatMoney(THRESHOLD_CENTS - totalCents) + '</strong> toe voor <strong>gratis verzending</strong>';
    }
  }

  function fetchAndUpdate() {
    fetch('/cart.js')
      .then(function(r) { return r.json(); })
      .then(function(cart) { updateBar(cart.total_price); });
  }

  document.addEventListener('cart:updated', fetchAndUpdate);
  document.addEventListener('cart-update', fetchAndUpdate);
  document.addEventListener('theme:cart:updated', fetchAndUpdate);

  (function patchFetch() {
    const _fetch = window.fetch;
    window.fetch = function(input, init) {
      return _fetch.apply(this, arguments).then(function(response) {
        const url = (typeof input === 'string') ? input : input.url;
        if (url && (url.includes('/cart/add') || url.includes('/cart/change') || url.includes('/cart/update'))) {
          setTimeout(fetchAndUpdate, 300);
        }
        return response;
      });
    };
  })();

  var observer = new MutationObserver(function(mutations) {
    mutations.forEach(function(m) {
      if (m.target && m.target !== document.getElementById('free-shipping-bar')) {
        fetchAndUpdate();
      }
    });
  });

  var cartTotals = document.querySelectorAll('[data-cart-subtotal], .cart-totals__total-value, [data-cart-total]');
  cartTotals.forEach(function(el) {
    observer.observe(el, { childList: true, subtree: true, characterData: true });
  });
})();
</script>
